entries[56444] = { ["name"] = "Würgeseuche", ["text"] = "Nahkampfreichweite\nWirken in 2 sek. 7 min Abklingzeit\nLässt einen Feind 1 Min. lang erkranken, erhöht dabei den körperlichen Schaden, den er erleidet, um 250 und verringert seine Ausdauer um 75. Das erkrankte Ziel hat eine Chance von 10%, seine Krankheit auf einen seiner in der Nähe befindlichen Verbündeten zu übertragen, wenn er im Gefecht getroffen wird.\n(Procchance: 10%)" }
entries[56445] = { ["name"] = "Würgeseuche", ["text"] = "10 Meter Reichweite\nSofort\nLässt einen Feind 1 Min. lang erkranken, erhöht dabei den körperlichen Schaden, den er erleidet, um 1500 und verringert seine Ausdauer um 200. Das erkrankte Ziel hat eine Chance von 10%, seine Krankheit auf einen seiner in der Nähe befindlichen Verbündeten zu übertragen, wenn er im Gefecht getroffen wird.\n(Procchance: 10%)" }
