entries[56448] = { ["name"] = "Sturmhammer", ["text"] = "20 Meter Reichweite\nWirken in 0.5 sek.\nSchleudert den Sturmhammer, um massiven Schaden zu verursachen und das Ziel 4 Sek. lang zu betäuben. Der Sturmhammer kehrt nach der Attacke zur Hand des Werfers zurück." }
