entries[56453] = { ["name"] = "Sichern und Laden", ["text"] = "Sofort\nWird ein Ziel durch Eure Eiskälte- oder Frostfalle gefangen, besteht eine Chance von 100%, und verursacht Eure Fähigkeit 'Schwarzer Pfeil' Schaden, besteht eine Chance von 20%, dass Eure nächsten 2 Anwendungen von 'Explosivschuss' keine Abklingzeit auslösen und keinen Fokus kosten. Der Effekt hält 12 Sek. lang an und kann nur einmal alle 10 Sek. ausgelöst werden." }
