entries[56458] = { ["name"] = "Aufladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nLädt das Ziel mit Elektrizität auf." }
entries[56459] = { ["name"] = "Spitzhammer", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nKobaltbarren (5)\n\"Kann als Spitzhacke oder Schmiedehammer verwendet werden.\"" }
entries[56460] = { ["name"] = "Kobaltsplitterbombe", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nEine Handvoll Kobaltbolzen (2), Unberechenbarer Sprengauslöser\n(3)\nBenötigt Ingenieurskunst\n(330)\nBenutzen: Fügt Zielen in einem Umkreis von 3 Metern ( 75 * 10) bis ( 100 * 10) Feuerschaden zu und macht sie 3 Sek. lang handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)" }
entries[56461] = { ["name"] = "Klingenhacke", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nKobaltbarren (5)\n\"Kann als Spitzhacke oder Kürschnermesser verwendet werden.\"" }
entries[56462] = { ["name"] = "Gnomisches Armeemesser", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (10), Kürschnermesser , Spitzhacke , Schmiedehammer\nBenutzen: Ein Ingenieur mit einer Fähigkeit von mindestens 350 kann die Batterien des Messers überladen, um zu versuchen, einen toten Verbündeten ins Leben zurückzurufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\n+10 Bergbau\n+10 Kräuterkunde\n+10 Kürschnern\n\"Beinhaltet einen gyromatischen Mikroregler, einen Bogenlichtschraubenschlüssel, Nasenbohrer, Schmiedehammer, Rückenkratzer und ein Kreiseldings.\"" }
entries[56463] = { ["name"] = "Explosiver Lockvogel", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFroststoff , Unberechenbarer Sprengauslöser (3)\n(5)\nBenötigt Ingenieurskunst\n(350)\nBenutzen: Beschwört einen Lockvogel, der explodiert, wenn er angegriffen wird, und Gegnern 1440 bis 2160 körperlichen Schaden zufügt. Hält 3 Min. lang an oder bis er explodiert. (2 Min Abklingzeit)\n\"Warnhinweis: Kann vorzeitig explodieren, wenn elektromagnetischem Puls ausgesetzt.\"" }
entries[56464] = { ["name"] = "Überladener Kondensator", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nKobaltbarren (4), Kristallisierte Erde" }
entries[56465] = { ["name"] = "Mechanische Schneebrille", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (8), Boreanisches Leder (2), Äonenschatten\nMechanische Schneebrille\nWird beim Anlegen gebunden\nKopf Stoff\n581 Rüstung\n<Zufällige Verzauberung>\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst\n(400)\nAnlegen: Vor Kälte geschützt. Euer Frostwiderstand ist um 20 erhöht." }
entries[56466] = { ["name"] = "Überschallbooster", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (4), Eine Handvoll Kobaltbolzen (2)\nÜberschallbooster\nWird beim Anlegen gebunden\nSchmuck\n+81 Ausdauer\nBenötigt Ingenieurskunst\n(390)\nAnlegen: In manchen Fällen schärft der Lärm von Nahkämpfen Euer Schallbewusstsein und erhöht 10 Sek. lang Eure Angriffskraft um 498 . Dieser Effekt kann pro Minute nur einmal auftreten. (Procchance: 35%, 50s Abklingzeit)" }
entries[56467] = { ["name"] = "Lärmmaschine", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (2), Eine Handvoll Kobaltbolzen (8)\nLärmmaschine\nWird beim Anlegen gebunden\nSchmuck\n+54 Intelligenz\nBenötigt Ingenieurskunst\n(390)\nAnlegen: Nahkampfangriffe auf Euch haben eine Chance, einen Schallschild zu beschwören, der 1273 Schaden absorbiert. Dieser Effekt kann nur einmal pro Minute auftreten. (Procchance: 50%, 50s Abklingzeit)" }
entries[56468] = { ["name"] = "Kiste voller Bomben", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nSaronitbarren (5), Unberechenbarer Sprengauslöser\n\"Beinhaltet Saronitbomben. Jede Menge Saronitbomben.\"\n<Zum Öffnen rechtsklicken>" }
entries[56469] = { ["name"] = "Gnomischer Blitzgenerator", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nTitanbarren (2), Saronitbarren (8), Äonenwasser (2), Äonenluft (2)\nGnomischer Blitzgenerator\nWird beim Aufheben gebunden\nSchmuck\nErhöht Eure kritische Trefferwertung um + 84.\nBenötigt Ingenieurskunst\n(425)\nBenutzen: Erzeugt einen Blitzstrahl, der einen Feind für 1953 Naturschaden trifft. Das ganze Gehäuse des Geräts ist aus Metall... (1 Min Abklingzeit)\n\"Garantiert sicher!\"" }
entries[56470] = { ["name"] = "Sonnenzielfernrohr", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nFroststahlröhre , Sonnenkristall , Herbstglimmer\nSonnenzielfernrohr\n70\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht das Distanzangriffstempo um 40 .\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[56471] = { ["name"] = "Froststahlröhre", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nKobaltbarren (8), Kristallisiertes Wasser" }
entries[56472] = { ["name"] = "MOLL-E", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (8), Äonenluft (8)\nMOLL-E\nWird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst\n(425)\nBenutzen: Erstellt 10 Min. lang einen tragbaren Briefkasten. MOLL-E wird nach seiner Nutzung nicht zerstört. (1 Stunde Abklingzeit)\n\"Mobiler optimierter Liebesbrief- und Lieferungsextraktor\"" }
entries[56473] = { ["name"] = "Gnomische Röntgenbrille", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer\nReagenzien:\nTitanbarren (6), Traumsplitter (2), Eine Handvoll Kobaltbolzen (2)\nGnomische Röntgenbrille\nWird beim Aufheben gebunden\nSpielzeug\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gnomeningenieur\nBenutzen: Ermöglicht es Euch, Spieler ohne Kleidung und Rüstung zu sehen." }
entries[56476] = { ["name"] = "Einspritzerset: Heiltrank", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (12), Eine Handvoll Kobaltbolzen (2)\n(8)\nBenutzen: Wandelt 20 runenverzierte Heiltränke zu einer kompakten Einspritzung.\n\"Mit Vorsicht verwenden.\"" }
entries[56477] = { ["name"] = "Einspritzerset: Manatrank", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSaronitbarren (12), Kristallisiertes Wasser (2)\n(8)\nBenutzen: Wandelt 20 runenverzierte Manatränke zu einer kompakten Einspritzung.\n\"Ausfallsicher.\"" }
