entries[56808] = { ["name"] = "Glyphe 'Schattenwandeln'", ["text"] = "Während Eure Fähigkeit 'Schattenwandeln' aktiv ist, wird zudem Eure Verstohlenheitsentdeckung erhöht.\nModifies Effect #2's Value +20:\nSchattenwandeln" }
entries[56809] = { ["name"] = "Glyphe 'Solarplexus'", ["text"] = "Um Eure Fähigkeit 'Solarplexus' anwenden zu können, muss das Ziel Euch nicht länger zugewandt sein." }
