entries[56815] = { ["name"] = "Runenstoß", ["text"] = "30 Runenmacht Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nSchlägt das Ziel und verursacht 200% Waffenschaden. Diesem Angriff kann nicht ausgewichen werden und er kann weder geblockt noch pariert werden." }
