entries[56820] = { ["name"] = "Glyphe 'Verkrüppelndes Gift'", ["text"] = "Erhöht Eure Chance, Ziele mit verkrüppelndem Gift zu vergiften, um zusätzliche 20%." }
entries[56825] = { ["name"] = "Arkane Explosion", ["text"] = "120 Mana\nSofort\nLässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden 3600 bis 4400 Arkanschaden zu." }
