entries[56829] = { ["name"] = "Glyphe 'Irreführung'", ["text"] = "Wenn Ihr Eure Fähigkeit 'Irreführung' auf Euer Tier anwendet, wird die Abklingzeit von 'Irreführung' sofort abgeschlossen." }
entries[56833] = { ["name"] = "Glyphe 'Besserung'", ["text"] = "Euer Zauber 'Tier heilen' heilt jetzt alle 1 Sek. und heilt zusätzliche 25% der Gesundheit Eures Begleiters im Verlauf seiner Dauer." }
entries[56835] = { ["name"] = "Sensenmann", ["text"] = "Wenn Ihr mit Euren Fähigkeiten 'Blutstoß', 'Pestilenz', 'Schwärender Stoß', 'Eisige Berührung' oder 'Siedendes Blut' einen Treffer erzielt, verwandeln sich die entsprechenden Runen bei ihrer Aktivierung zu einer Todesrune. Eine Todesrune zählt als Blut-, Frost- oder unheilige Rune.\n(100ms Abklingzeit)" }
entries[56837] = { ["name"] = "Frostblitz", ["text"] = "90 Mana\nWirken in 3 sek.\nFügt in der Nähe befindlichen Gegnern Frostschaden zu und verringert 4 Sek. lang ihr Bewegungstempo." }
