entries[56843] = { ["name"] = "Salve", ["text"] = "10 - 70 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nFeuert kontinuierlich eine Salve Munition auf das Zielgebiet und verursacht 6 Sek. lang pro Sekunde 1157 bis 1343 Arkanschaden bei feindlichen Zielen im Umkreis von 8 Metern." }
