entries[56854] = { ["name"] = "Gegentritt", ["text"] = "Nahkampfreichweite\nSofort\nEin schneller Tritt, der einem einzelnen Gegner 275 Schaden zufügt. Er unterbricht außerdem das Wirken von Zaubern und verhindert 4 Sek. lang, dass weitere Zauber dieser Art gewirkt werden." }
entries[56855] = { ["name"] = "Wirbelschlag", ["text"] = "Sofort\nBenötigt Nahkampfwaffe\nFührt einen wirbelnden Angriff durch, der allen in der Nähe befindlichen Feinden Waffenschaden plus 150% zufügt und sie zurückstößt." }
entries[56858] = { ["name"] = "Flammenstoß", ["text"] = "260 Mana 30 Meter Reichweite\nWirken in 3 sek.\nLässt eine Flammensäule niedergehen, die alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 8 Sek. lang alle 2 Sek. zusätzlichen Schaden zufügt." }
