entries[56861] = { ["name"] = "Windstoß", ["text"] = "645 Mana 60 Meter Reichweite\nSofort\nIhr beschwört einen wilden Taifun, der feindlichen Zielen bei Kontakt 602 bis 698 Naturschaden zufügt und sie 5 Meter zurückstößt." }
