entries[56908] = { ["name"] = "Flammenatem", ["text"] = "45 Meter Reichweite\nWirken in 2 sek.\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 8750 bis 11250 Feuerschaden zu." }
