entries[56925] = { ["name"] = "Frostschlingen", ["text"] = "150 Meter Reichweite\nWirken in 1.5 sek.\nFrostfeuertentakel umschlingen das Ziel und verursachen 2188 bis 2812 Frostschaden." }
entries[56926] = { ["name"] = "Donnerschock", ["text"] = "30 Meter Reichweite\nSofort\nLässt eine Blitzschlagwolke entstehen, die 10 Sek. anhält und allen Feinden im ausgewählten Gebiet 1575 bis 2025 Naturschaden und alle 2 Sek. 1575 bis 2025 zusätzlichen Schaden zufügt." }
entries[56933] = { ["name"] = "Brandschuss", ["text"] = "5 - 45 Meter Reichweite\nWirken in 1 sek.\nEin Schuss, der 1890 bis 2310 Feuerschaden verursacht sowie 12 Sek. lang alle 3 Sek. 750 zusätzlichen Feuerschaden." }
entries[56934] = { ["name"] = "Feuerbombe", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nVerursacht Feuerschaden bei einem Feind und seinen nahen Verbündeten." }
entries[56935] = { ["name"] = "Eisnova", ["text"] = "Wirken in 2 sek.\nVerursacht bei allen Feinden innerhalb von 60 Metern 3299 bis 3701 Frostschaden und betäubt sie 3 Sek. lang." }
entries[56936] = { ["name"] = "Blizzard", ["text"] = "200 Mana 40 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nRuft einen Blizzard herbei, der 6 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 2000 Frostschaden zufügt." }
entries[56937] = { ["name"] = "Eisdorn", ["text"] = "Unbegrenzte Reichweite\nWirken in 0.5 sek.\nFügt einem feindlichen Ziel 875 bis 1125 Frostschaden zu. Bei eingefrorenen Zielen wird dreifacher Schaden zugefügt." }
entries[56938] = { ["name"] = "Versengen", ["text"] = "50 Mana 30 Meter Reichweite\nWirken in 1 sek.\nVersengt den Feind und fügt ihm Feuerschaden zu." }
entries[56939] = { ["name"] = "Feuerschlag", ["text"] = "120 Mana 20 Meter Reichweite\nSofort\nFügt einem Gegner Feuerschaden zu." }
entries[56940] = { ["name"] = "Thorim Story Kill Credit" }
entries[56941] = { ["name"] = "Die Abrechnung beobachten" }
entries[56943] = { ["name"] = "Glyphe 'Rasende Regeneration'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nNach der Aktivierung von 'Rasende Regeneration' sind auf Euch gewirkte Heileffekte 6 Sek. lang 40% mächtiger. Allerdings kostet Eure 'Rasende Regeneration' nun immer 50 Wut und wandelt Wut nicht mehr in Gesundheit um." }
entries[56944] = { ["name"] = "Glyphe 'Omen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend kein Finsterniszustand aktiv ist, gewähren Euch die folgenden Fähigkeiten 10 Solar- oder Lunarenergie: 'Wucherwurzeln', 'Wirbelsturm', 'Feenfeuer', 'Feenschwarm', 'Massenumschlingung', 'Taifun', 'Desorientierendes Gebrüll', 'Ursols Vortex' und 'Mächtiger Hieb'." }
entries[56945] = { ["name"] = "Glyphe 'Heilende Berührung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Euren Zauber 'Heilende Berührung' wirkt, wird die Abklingzeit von 'Schnelligkeit der Natur' um 3 Sek. verringert." }
entries[56946] = { ["name"] = "Glyphe 'Hurrikan'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Zauber 'Hurrikan' und 'Astralsturm' verringern nun das Bewegungstempo betroffener Ziele um 50%." }
entries[56947] = { ["name"] = "Glyphe 'Anregen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Euer Zauber 'Anregen' auf ein anderes Ziel gewirkt wird, als auf Euch selbst, profitieren beide Parteien davon. Der Effekt wird jedoch um 40% verringert." }
entries[56948] = { ["name"] = "Glyphe 'Orca'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Wassergestalt erscheint nun als Orca." }
entries[56949] = { ["name"] = "Glyphe 'Erblühen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Erblühen' wird durch Wildpilze verursacht anstatt durch 'Rasche Heilung'. 'Erblühen' hält so lange an, wie ein Wildpilz aktiv ist. Erhöht die durch 'Rasche Heilung' hervorgerufene Heilung um 20%." }
entries[56950] = { ["name"] = "Glyphe 'Hirsch'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Reisegestalt kann nun Gruppenmitgliedern als Reittier dienen. Diese Glyphe wird deaktiviert, solange Glyphe 'Gepard' aktiv ist." }
entries[56951] = { ["name"] = "Glyphe 'Wildes Brüllen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Wildes Brüllen' kann nun gänzlich ohne Compopunkte eingesetzt werden, was zu einer Dauer von 12 Sek. führt." }
entries[56952] = { ["name"] = "Glyphe 'Anspringen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Reichweite Eurer Fähigkeit 'Anspringen' um 8 Meter." }
entries[56953] = { ["name"] = "Glyphe 'Wiedergeburt'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nSpieler, die durch Euren Zauber 'Wiedergeburt' ins Leben zurückgerufen wurden, kehren mit 100% Gesundheit zurück." }
entries[56954] = { ["name"] = "Glyphe 'Nachwachsen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die kritische Trefferchance Eures Zaubers 'Nachwachsen' um 40%, entfernt aber den regelmäßigen Heileffekt." }
entries[56955] = { ["name"] = "Glyphe 'Verjüngung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Euer Zauber 'Verjüngung' auf drei oder mehr Zielen aktiv ist, wird die Zauberzeit von 'Pflege' um 30% verringert." }
entries[56956] = { ["name"] = "Glyphe 'Schleichen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Einschränkung des Bewegungstempos beim Schleichen um 100%." }
entries[56957] = { ["name"] = "Glyphe 'Schreddern'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend 'Berserker' oder 'Tigerfuror' aktiv sind, hat 'Schreddern' keine Positionsvoraussetzungen mehr." }
entries[56958] = { ["name"] = "Glyphe 'Schädelstoß'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Unterbrechungsdauer Eurer Fähigkeit 'Schädelstoß' um 2 Sek., erhöht jedoch die Abklingzeit um 5 Sek." }
entries[56959] = { ["name"] = "Glyphe 'Gelenkte Sterne'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Sternenregen' trifft nur Ziele, die von Euren Zaubern 'Mondfeuer' oder 'Sonnenfeuer' betroffen sind." }
entries[56960] = { ["name"] = "Glyphe 'Stampede'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt 'Anstachelndes Gebrüll' nun außerhalb von Katzen- oder Bärengestalt einsetzen." }
entries[56961] = { ["name"] = "Glyphe 'Zermalmen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Zermalmen' trifft 1 zusätzliches Ziel für 50% des Schadens." }
entries[56963] = { ["name"] = "Glyphe 'Griff der Natur'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Griff der Natur' um 45 Sek." }
entries[56965] = { ["name"] = "Glyphe 'Sterne'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Druide\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Mondkingestalt erscheint nun als Astralgestalt, gewährt weiterhin dieselben Boni, lässt Euch aber als astral verstärkte Version Eurer normalen, humanoiden Gestalt erscheinen." }
entries[56966] = { ["name"] = "Grenzwarnung", ["text"] = "Unbegrenzte Reichweite\nSofort\nEuer Fahrzeug befindet sich außerhalb der Begrenzung. Kehrt sofort auf das Schlachtfeld zurück!" }
entries[56969] = { ["name"] = "Arkanschlag", ["text"] = "30 Meter Reichweite\nWirken in 2.5 sek.\nÜberzieht einen Feind mit Energie und verursacht 4375 bis 5625 Arkanschaden. Jedes Mal, wenn Ihr 'Arkanschlag' wirkt, verringert sich die Zauberzeit. Dieser Effekt ist bis zu 5-mal stapelbar und hält 8 Sek. lang an." }
entries[56971] = { ["name"] = "Glyphe 'Ungebundenes Mana'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Manaedelstein stellt nun statt mit sofortiger Wirkung im Verlauf von 6 Sek. Mana wieder her." }
entries[56972] = { ["name"] = "Glyphe 'Arkane Explosion'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Radius von 'Arkane Explosion' um 5 Meter." }
entries[56973] = { ["name"] = "Glyphe 'Blinzeln'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Teleportdistanz Eures Zaubers 'Blinzeln' um 8 Meter." }
entries[56974] = { ["name"] = "Glyphe 'Hervorrufung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25" }
entries[56975] = { ["name"] = "Glyphe 'Einäschern'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den direkten Schaden, die Dauer des regelmäßigen Schadens und die Abklingzeit von 'Einäschern' um 100%." }
entries[56976] = { ["name"] = "Glyphe 'Frostnova'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Frostnova' um 5 Sek." }
entries[56978] = { ["name"] = "Glyphe 'Momentum'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blinzeln' teleportiert Euch in die Richtung, in die Ihr Euch bewegt, statt in Eure Blickrichtung." }
entries[56979] = { ["name"] = "Glyphe 'Eisblock'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn der Effekt 'Eisblock' abläuft, wird eine kostenlose Frostnova ausgelöst und Ihr seid 3 Sek. lang immun gegenüber allen Zaubern." }
entries[56980] = { ["name"] = "Glyphe 'Zersplitterndes Eis'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Eislanze' und Eure Eiszapfen treffen jetzt 1 zusätzliches Ziel und fügen ihm 50% Schaden zu." }
entries[56981] = { ["name"] = "Glyphe 'Kältekegel'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den von 'Kältekegel' verursachten Schaden um 200%." }
entries[56983] = { ["name"] = "Glyphe 'Schnelle Deplatzierung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blinzeln' hat jetzt 2 Aufladungen mit einer Aufladungszeit von 15 Sek., befreit Euch aber nicht mehr von Betäubungs- und Bewegungsunfähigkeitseffekten." }
entries[56984] = { ["name"] = "Glyphe 'Manaedelstein'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Manaedelstein herbeizaubern' erzeugt nun einen brillanten Manaedelstein, der über bis zu 10 Aufladungen verfügt." }
entries[56986] = { ["name"] = "Glyphe 'Kleintierverwandlung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Euer Zauber 'Verwandlung' auf Kleintiere gewirkt wird, hält er 24 Stunden lang an und kann auf mehrere Ziele gewirkt werden." }
entries[56987] = { ["name"] = "Glyphe 'Verwandlung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Verwandlung' entfernt zusätzlich alle auf das Ziel wirkenden Effekte, die Schaden über Zeit verursachen." }
entries[56988] = { ["name"] = "Glyphe 'Eisige Adern'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Eisige Adern' bewirkt, dass Eure Zauber 'Frostblitz', 'Frostfeuerblitz', 'Eislanze' und der Zauber 'Wasserblitz' Eures Wasserelementars in jeweils 3 kleinere Blitze aufgeteilt werden, die 40% Schaden verursachen, anstatt das Zaubertempo zu erhöhen." }
entries[56989] = { ["name"] = "Glyphe 'Zauberraub'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr erfolgreich einen Zauber raubt, werdet Ihr zusätzlich um 5% Eurer maximalen Gesundheit geheilt." }
entries[56990] = { ["name"] = "Glyphe 'Fluch aufheben'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den von Euch verursachten Schaden 10 Sek. lang um 5%, wenn Ihr erfolgreich einen Fluch aufgehoben habt." }
entries[56991] = { ["name"] = "Glyphe 'Arkane Macht'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Magier\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Wirkungsdauer und die Abklingzeit von 'Arkane Macht' um 100%." }
entries[56994] = { ["name"] = "Glyphe 'Aspekte'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr in einen anderen Aspekt wechselt, folgt Euch 15 Sek. lang ein Abbild dieses neuen Aspektes." }
entries[56995] = { ["name"] = "Glyphe 'Camouflage'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Camouflage' gewährt Euch nun selbst wenn Ihr Euch bewegt einen Verstohlenheitseffekt, Euer Bewegungstempo wird, während die Fähigkeit aktiv ist, jedoch um 50% verringert." }
entries[56996] = { ["name"] = "Glyphe 'Befreiung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Eure Fähigkeit 'Rückzug' nutzt, werdet Ihr um 5% Eurer gesamten Gesundheit geheilt." }
entries[56997] = { ["name"] = "Glyphe 'Besserung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Tier heilen' heilt jetzt alle 1 Sek. und heilt zusätzliche 25% der Gesundheit Eures Begleiters im Verlauf seiner Dauer." }
entries[56998] = { ["name"] = "Glyphe 'Ablenkender Schuss'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Ablenkender Schuss' lenkt die Aufmerksamkeit des Ziel nun auf Euer Tier statt auf Euch." }
entries[56999] = { ["name"] = "Glyphe 'Endloser Zorn'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend 'Zorn des Wildtiers' aktiv ist, kann Euer Tier zwar Schaden erleiden aber nicht getötet werden." }
entries[57000] = { ["name"] = "Glyphe 'Abschreckung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die von Eurer Fähigkeit 'Abschreckung' gewährte Schadensverringerung um 20%." }
entries[57001] = { ["name"] = "Glyphe 'Rückzug'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Rückstoßentfernung von 'Rückzug'." }
entries[57002] = { ["name"] = "Glyphe 'Eiskältefalle'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEndet der Effekt Eurer Eiskältefalle, wird das Bewegungstempo des Ziels 4 Sek. lang um 70% verringert." }
entries[57003] = { ["name"] = "Glyphe 'Frostfalle'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Effektradius Eurer Frostfalle um 2 Meter." }
entries[57004] = { ["name"] = "Glyphe 'Irreführung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Eure Fähigkeit 'Irreführung' auf Euer Tier anwendet, wird die Abklingzeit von 'Irreführung' sofort abgeschlossen." }
entries[57005] = { ["name"] = "Glyphe 'Sprengfalle'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Sprengfalle verursacht keinen Schaden mehr, sondern stößt stattdessen bei der Explosion der Falle alle im Effektbereich befindlichen Gegner zurück." }
entries[57006] = { ["name"] = "Glyphe 'Geistbande'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Euer Begleiter aktiv ist, wird sowohl Eure erhaltene Heilung als auch die Eures Tiers um 10% erhöht." }
entries[57007] = { ["name"] = "Glyphe 'Kein Entkommen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die kritische Distanztrefferchance aller Eurer Angriffe gegen Ziele, die vom Effekt Eurer Eiskältefalle betroffen sind, um 100%." }
entries[57008] = { ["name"] = "Glyphe 'Orientierung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Tempobonus Eures 'Aspekt des Geparden' und 'Aspekt des Rudels' um 8% und erhöht Euer Reittempo um 10%. Die Erhöhung des Reittempos ist nicht mit anderen Effekten stapelbar." }
entries[57009] = { ["name"] = "Glyphe 'Wildtier zähmen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Kanalisierungsdauer von 'Wildtier zähmen' um 4 Sek." }
entries[57010] = { ["name"] = "Glyphe 'Schlangenfalle'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDie von Eurer Schlangenfalle beschworenen Schlangen erleiden durch Flächeneffekte 90% weniger Schaden." }
entries[57011] = { ["name"] = "Glyphe 'Gezielter Schuss'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Gezielter Schuss' kann nun aus der Bewegung heraus eingesetzt werden." }
entries[57012] = { ["name"] = "Glyphe 'Tier heilen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nGewährt Eurem Zauber 'Tier heilen' eine Chance von 100%, pro Tick 1 Fluch-, Krankheits-, Magie- oder Gifteffekt von Eurem Tier zu entfernen." }
entries[57014] = { ["name"] = "Glyphe 'Linderung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Jäger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Eiskältefalle' und 'Streuschuss' entfernen alle auf das Ziel wirkenden regelmäßigen Schadenseffekte." }
entries[57019] = { ["name"] = "Glyphe 'Fokussierter Schild'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Schild des Rächers' trifft 2 Ziele weniger, verursacht jedoch 30% mehr Schaden." }
entries[57020] = { ["name"] = "Glyphe 'Unaufhaltsamer Zorn'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Heiliger Zorn' fügt Zielen, die über weniger als 20% Gesundheit verfügen, 50% mehr Schaden zu." }
entries[57021] = { ["name"] = "Glyphe 'Mahnwort'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGlyphe 'Mahnende Worte'\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Wort der Herrlichkeit' kann jetzt gegen gegnerische Ziele eingesetzt werden und fügt ihnen Heiligschaden in etwa der Höhe der ansonsten geheilten Menge zu.\n\nFunktioniert nicht mit 'Ewige Flamme'." }
entries[57022] = { ["name"] = "Glyphe 'Göttlicher Schutz'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nReduziert den Magieschaden verringernden Effekt Eures Zaubers 'Göttlicher Schutz' auf 20%, lässt ihn dafür aber zusätzlich den erlittenen körperlichen Schaden um 20% verringern." }
entries[57023] = { ["name"] = "Glyphe 'Weihe'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt nun den Effektbereich Eures Zaubers 'Weihe' in einem Umkreis von 25 Metern frei platzieren." }
entries[57024] = { ["name"] = "Glyphe 'Zornige Vergeltung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Euer Zauber 'Zornige Vergeltung' aktiv ist, werdet Ihr alle 2 Sek. um 1% Eurer maximalen Gesundheit geheilt." }
entries[57025] = { ["name"] = "Glyphe 'Blendendes Licht'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Blendendes Licht' stößt Ziele 3 Sek. lang zu Boden, statt sie zu blenden." }
entries[57026] = { ["name"] = "Glyphe 'Wort der Herrlichkeit'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den Schaden pro verbrauchter heiliger Kraft nach dem Wirken von 'Wort der Herrlichkeit' oder 'Ewige Flamme' auf ein verbündetes Ziel um 3%. Hält 6 Sek. lang an." }
entries[57027] = { ["name"] = "Glyphe 'Heiliger Zorn'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Heiliger Zorn' betäubt auch Elementare, Drachkin und Entartungen." }
entries[57028] = { ["name"] = "Glyphe 'Urteil des Templers'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nNachdem Ihr mit 'Urteil des Templers' oder 'Exorzismus' Schaden verursacht habt, erleidet Ihr 6 Sek. lang 10% weniger Schaden." }
entries[57029] = { ["name"] = "Glyphe 'Illumination'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nKlassen: Paladin\n25\nBenutzen:\nKritische Effekte Eures Zaubers 'Heiliger Schock' regenerieren sofort 1% Eures Manas, Euer passiver Effekt 'Meditation' regeneriert jedoch 10% weniger Mana." }
entries[57030] = { ["name"] = "Glyphe 'Doppelbestrafung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Euren Zauber 'Richturteil' auf ein Ziel wirkt, wird der Schaden des nächsten Wirkens von 'Richturteil' auf ein zweites Ziel um 20% erhöht." }
entries[57031] = { ["name"] = "Glyphe 'Göttlichkeit'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Abklingzeit Eures Zaubers 'Handauflegung' um 2 Min., er regeneriert jedoch sofort 10% Eures maximalen Manas." }
