entries[57034] = { ["name"] = "Glyphe 'Gesegnetes Leben'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEs besteht eine Chance von 50%, dass Ihr eine Aufladung heiliger Kraft erhaltet, wenn Ihr mit einem Betäubungs-, Furcht- oder Bewegungsunfähigkeitseffekt belegt werdet.\n\nDieser Effekt kann nur ein Mal alle 20 Sek. auftreten. (Procchance: 50%, 20s Abklingzeit)" }
entries[57035] = { ["name"] = "Glyphe 'Licht der Morgendämmerung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Paladin\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Licht der Morgendämmerung' trifft 2 Ziele weniger, die Heilung pro Ziel wird jedoch um 25% erhöht." }
