entries[57129] = { ["name"] = "Glyphe 'Venensturz'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Schurke\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Venenschnitt' erhöht jetzt auch den Schaden gegen Ziele, die von Eurer Fähigkeit 'Blutsturz' betroffen sind." }
