entries[57138] = { ["name"] = "Erfrischung", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. 22502 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 35 Zaubermacht und 30 Ausdauer." }
entries[57139] = { ["name"] = "Satt", ["text"] = "Sofort\nZaubermacht um 35 , Ausdauer um 30 erhöht. Hält 1 Stunde lang an." }
entries[57140] = { ["name"] = "Hinterhalt", ["text"] = "Sofort\nErhöht die Reichweite Eurer Fähigkeit 'Hinterhalt' um 5 Meter." }
entries[57141] = { ["name"] = "Körperteilung" }
entries[57142] = { ["name"] = "Klingenwirbel", ["text"] = "Sofort\nWährend Eure Fähigkeit 'Klingenwirbel' aktiv ist, wird Eure Chance, Gegner mit nicht-tödlichen Giften zu vergiften, um 30% erhöht." }
entries[57143] = { ["name"] = "Explosion des Lebens", ["text"] = "50 Energie Unbegrenzte Reichweite\nSofort\nEntlädt einen Stoß verjüngender Energie, der befreundete Einheiten innerhalb von 60 Metern heilt und die vom Zaubernden hervorgerufene Heilung um 50% erhöht. Erhöht die Heilung und verlängert den Effekt pro Combopunkt:\n1 Punkt: 5.000 Heilung / 5 Sek.\n2 Punkte: 7.500 Heilung / 10 Sek.\n3 Punkte: 10.000 Heilung / 15 Sek.\n4 Punkte: 12.500 Heilung / 20 Sek.\n5 Punkte: 15.000 Heilung / 25 Sek." }
entries[57144] = { ["name"] = "Scharfe Klingen", ["text"] = "Sofort\nErhöht Eure Chance, Ziele mit verkrüppelndem Gift zu vergiften, um zusätzliche 20%." }
entries[57145] = { ["name"] = "Gesundung", ["text"] = "Sofort\nErhöht die Heilung durch Eure Fähigkeit 'Gesundung' um zusätzlich 1.0% Eurer maximalen Gesundheit." }
entries[57146] = { ["name"] = "Entrinnen", ["text"] = "Sofort\nErhöht die Dauer Eurer Fähigkeit 'Entrinnen' um 5 Sek." }
entries[57147] = { ["name"] = "Genesung", ["text"] = "Sofort\nEure Fähigkeiten 'Ausweiden' und 'Vergiften' verringern zusätzlich das Bewegungstempo des Ziels 6 Sek. lang um 50%." }
entries[57148] = { ["name"] = "Rüstung schwächen", ["text"] = "Sofort\nEure Fähigkeit 'Rüstung schwächen' belegt das Ziel mit drei Stapeln von 'Rüstungsschwächung'." }
entries[57149] = { ["name"] = "Finte", ["text"] = "Sofort\nErhöht die Dauer Eurer Fähigkeit 'Finte' um 2 Sek." }
entries[57150] = { ["name"] = "Erdrosseln", ["text"] = "Sofort\nErhöht die Dauer des Stilleeffekts Eurer Fähigkeit 'Erdrosseln' um 1.0 Sek." }
