entries[57153] = { ["name"] = "Glyphe 'Blutige Heilung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die durch Bandagen erhaltene Heilung um 20%, während der Effekt 'Tiefe Wunden' aktiv ist." }
entries[57154] = { ["name"] = "Glyphe 'Verwehrende Stöße'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nEure Fähigkeiten 'Heldenhafter Stoß' und 'Spalten' verlangsamen das Ziel 8 Sek. lang um 50%.\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Heldenhafter Stoß' und 'Spalten' verlangsamen das Ziel 8 Sek. lang um 50%." }
entries[57155] = { ["name"] = "Glyphe 'Heftige Rückwirkungen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Eure Fähigkeit 'Schildblock' aktiv ist, verursacht Eure Fähigkeit 'Schildschlag' 50% mehr Schaden." }
entries[57156] = { ["name"] = "Glyphe 'Blutdurst'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die von Eurer Fähigkeit 'Blutdurst' hervorgerufene Heilung um 100%." }
