entries[57158] = { ["name"] = "Glyphe 'Auf die Kehle zielen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeiten 'Zuschlagen' und 'Heldenhafter Wurf' bringen das Ziel zusätzlich 3 Sek. lang zum Schweigen. Funktioniert nicht gegen Spielercharaktere." }
