entries[57161] = { ["name"] = "Glyphe 'Durch das Schwert umkommen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend 'Durch das Schwert umkommen' aktiv ist, erhöht der Einsatz von 'Überwältigen' die Dauer des Effekts um 1 Sek. und der Einsatz von 'Wilder Stoß' erhöht die Dauer um 0.5 Sek. pro Anwendung." }
entries[57162] = { ["name"] = "Glyphe 'Wütende Eile'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr Euch in einem Wutzustand befindet, bewegt Ihr Euch 20% schneller." }
entries[57163] = { ["name"] = "Glyphe 'Kniesehne'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr Wut ausgebt, um Eure Fähigkeit 'Kniesehne' einzusetzen, werden die Wutkosten des nächsten Einsatzes von 'Kniesehne' um 100% verringert." }
entries[57164] = { ["name"] = "Glyphe 'Nachhallende Kraft'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht den verursachten Schaden und die Abklingzeit Eurer Fähigkeit 'Donnerknall' um 50%." }
