entries[57172] = { ["name"] = "Glyphe 'Wütender Wind'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Krieger\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nTreffer mit Eurer Fähigkeit 'Wütender Schlag' erhöhen den Schaden Eures nächsten Einsatzes von 'Wirbelwind' um 10%. (1s Abklingzeit)" }
entries[57181] = { ["name"] = "Glyphe 'Kreis der Heilung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Kreis der Heilung' heilt 1 zusätzliches Ziel, seine Manakosten werden jedoch um 35% erhöht." }
