entries[57190] = { ["name"] = "Glyphe 'Massenbannung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Massenbannung' wird mächtig genug, magische Effekte zu entfernen, die normalerweise nicht gebannt werden können." }
entries[57191] = { ["name"] = "Glyphe 'Psychisches Entsetzen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Abklingzeit Eures Zaubers 'Psychisches Entsetzen' um 10 Sek." }
