entries[57198] = { ["name"] = "Glyphe 'Geißelgefangennahme'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Zauberzeit Eures Zaubers 'Untote fesseln' um 1.0 Sek." }
entries[57199] = { ["name"] = "Glyphe 'Gedankenschlag'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Priester\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Euer Zauber 'Gedankenschlag' einen kritischen Treffer erzielt, wird das Ziel 4 Sek. lang bewegungsunfähig." }
