entries[57209] = { ["name"] = "Glyphe 'Spuk'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nGeringe Glyphe\nKlassen: Todesritter\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Totenerweckung' ruft nun einen Spuk herbei, statt eines Ghuls." }
