entries[57216] = { ["name"] = "Glyphe 'Wechselnde Präsenzen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Todesritter\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr behaltet 70% eurer Runenmacht bei, wenn Ihr die Präsenz wechselt. (Procchance: 10%)" }
