entries[57246] = { ["name"] = "Glyphe 'Wasserschreiter'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nGeringe Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr erlangt automatisch den Effekt 'Wasserwandeln', wenn Ihr Euch in Geisterwolfgestalt befindet." }
entries[57247] = { ["name"] = "Glyphe 'Totem der Erdung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nStatt einen Zauber zu absorbieren, reflektiert Euer Totem der Erdung den nächsten Schadenszauber zurück auf den Zaubernden, jedoch wird die Abklingzeit Eures Totems der Erdung um 20 Sek. erhöht." }
