entries[57249] = { ["name"] = "Glyphe 'Lavapeitsche'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Lavapeitsche' breitet den Effekt von 'Flammenschock' nicht mehr auf in der Nähe befindliche Gegner aus." }
entries[57250] = { ["name"] = "Glyphe 'Kettenbildung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Sprungreichweite Eures Zaubers 'Kettenheilung' um 100%, gibt dem Zauber aber eine Abklingzeit von 2 Sek." }
entries[57251] = { ["name"] = "Glyphe 'Wasserschild'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Perlmutttinte (3)\nErhebliche Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die reaktive Manaregeneration Eures Zaubers 'Wasserschild' nach Angriffen um 50%, die passive Manaregeneration wird aber um 15% verringert." }
entries[57252] = { ["name"] = "Glyphe 'Läuterndes Wasser'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nErhebliche Glyphe\nKlassen: Schamane\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr einen schädlichen Zaubereffekt oder Fluch von einem Verbündeten bannt, heilt Ihr das Ziel gleichzeitig um 5% Eurer maximalen Gesundheit." }
