entries[57257] = { ["name"] = "Glyphe 'Hand von Gul'dan'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Hand von Gul'dan' kann auf eine Position gezielt eingesetzt werden." }
entries[57258] = { ["name"] = "Glyphe 'Feuersbrunst'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Feuersbrunst' setzt nicht mehr voraus, dass das Ziel von 'Feuerbrand' betroffen ist, um es zu verlangsamen." }
entries[57259] = { ["name"] = "Glyphe 'Lebensentzug'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber [ Feuerbrand : 'Feuerbrand' ] 'Verderbnis' heilt Euch um 0.5% Eurer Maximalgesundheit, wenn er [ Feuerbrand : regelmäßigen ] Schaden verursacht." }
entries[57260] = { ["name"] = "Glyphe 'Tiefgrüne Sphären'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n[ Zerstörung : Aktive instabile Funken werden als grüne Sphären dargestellt, die um Euren Charakter wirbeln /\n\nGebrechen, Dämonologie\nEure Seelensplitter werden in grüne Sphären umgewandelt ]" }
entries[57261] = { ["name"] = "Glyphe 'Alpträume'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Teufelsross und Euer Schreckensross können übers Wasser hinwegreiten und hinterlassen eine Flammenspur." }
entries[57262] = { ["name"] = "Glyphe 'Furcht'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt das Ziel Eures Zaubers 'Furcht' vor Furcht erstarren, anstatt dass es flüchtet." }
entries[57263] = { ["name"] = "Glyphe 'Teufelswache'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Teufelswache wird sich mit einer zufälligen Waffe der folgenden Arten ausrüsten, die sich in Euren Taschen befindet: Zweihandaxt, Zweihandschwert oder Stangenwaffe." }
entries[57264] = { ["name"] = "Glyphe 'Dämonisches Training'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerbessert die Spezialfähigkeiten Eures Dämons:\n\nVerringert die Zauberzeit des Zaubers 'Feuerblitz' Eures [ Grimoire der Überlegenheit : Teufelswichtels / Wichtels] um 50% und es werden 3 Blitze abgefeuert.\n\nErhöht die gesamte Rüstung Eures [ Grimoire der Überlegenheit : Leerenfürsten / Leerwandlers] um 10%.\n\nDie Fähigkeit [ Grimoire der Überlegenheit : 'Mesmerisieren' / 'Verführung'] [ Grimoire der Überlegenheit : Eurer Shivarra und Eures Erzinkubus / Eures Succubus und Inkubus] entfernt zusätzlich alle regelmäßigen Schadenseffekte vom Ziel.\n\nWenn Euer [ Grimoire der Überlegenheit : Beobachter / Teufelsjäger] die Fähigkeit [ Grimoire der Überlegenheit : 'Magie kopieren' / 'Magie verschlingen'] einsetzt, werdet Ihr um die gleiche Menge geheilt.\n\nErhöht die gesamte Gesundheit [ Grimoire der Überlegenheit : Eures Zornwächters / Eurer Teufelswache] um 20%." }
entries[57265] = { ["name"] = "Glyphe 'Lebenslinie'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Lebenslinie' stellt sofort 15% der Gesundheit Eures Dämons wieder her, hat jedoch eine Abklingzeit von 10 Sek." }
entries[57266] = { ["name"] = "Glyphe 'Gesundheitsstein'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Mitternachtstinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr gewinnt durch das Nutzen von Gesundheitssteinen 100% mehr Gesundheit, der Effekt wird jedoch zu einer regelmäßigen Heilung, die im Verlauf von 10 Sek. erfolgt." }
entries[57267] = { ["name"] = "Glyphe 'Subtilität'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Seelensplitter werden außerhalb des Kampfes nicht mehr angezeigt." }
entries[57268] = { ["name"] = "Glyphe 'Fluch der Elemente'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Fluch der Elemente' trifft 2 zusätzliche Ziele in der Nähe." }
entries[57269] = { ["name"] = "Glyphe 'Wichtelschwarm'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Löwentinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBenötigt Dämonologie.\nLehrt Euch den Zauber 'Wichtelschwarm'.\n\nWichtelschwarm\nBeschwört 4 Wildwichtel aus dem Wirbelnden Nether, die das Ziel angreifen.\n\nDer passive Effekt von 'Wildwichtel' ist inaktiv, während der Zauber abklingt. Die Abklingzeit von 'Wichtelschwarm' wird von Tempo verringert. Erhöht außerdem die Abklingzeit von 'Wildwichtel' um 4 Sek." }
entries[57270] = { ["name"] = "Glyphe 'Verwüstung'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Zauber 'Verwüstung' erhält 3 zusätzliche Aufladungen, die Abklingzeit wird jedoch um 35 Sek. erhöht." }
entries[57271] = { ["name"] = "Glyphe 'Schattenblitz'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nTeilt Euren Schattenblitz in drei kleinere Geschosse auf." }
entries[57274] = { ["name"] = "Glyphe 'Seelenstein'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Firmamenttinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nSpielercharaktere, die sich durch einen Seelenstein wiederbeleben, erstehen mit 100% Gesundheit auf." }
entries[57275] = { ["name"] = "Glyphe 'Aasschwarm'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Astraltinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Aasschwarm' stößt Ziele nicht mehr zurück." }
entries[57276] = { ["name"] = "Glyphe 'Instabiles Gebrechen'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nErhebliche Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Zauberzeit von 'Instabiles Gebrechen' um 25%." }
entries[57277] = { ["name"] = "Glyphe 'Fallender Meteor'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Jadefeuertinte (3)\nGeringe Glyphe\nKlassen: Hexenmeister\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr aus dem Fallen heraus 'Dämonischer Sprung' wirkt, schlagt Ihr mit Wucht in den Boden ein, der Fallschaden bringt Euch jedoch nicht um." }
entries[57283] = { ["name"] = "Pilzkraft aufheben" }
entries[57285] = { ["name"] = "Erfrischung", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. 22502 Gesundheit wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 30 kritischen Trefferwert und 30 Ausdauer." }
entries[57286] = { ["name"] = "Satt", ["text"] = "Sofort\nKritischer Trefferwert um 30 , Ausdauer um 30 erhöht. Hält 1 Stunde lang an." }
